require_once '../config/database.php';require_once '../config/response.php';$p=trim($_GET['protocolo']??'');if($p==='')jsonResponse(false,'Informe o protocolo.',[],400);$s=$conn->prepare('SELECT id,protocolo,cliente_nome,equipamento,status,prazo,valor_estimado,valor_final,criado_em FROM servicos WHERE empresa_id=2 AND protocolo=? LIMIT 1');$s->bind_param('s',$p);$s->execute();$serv=$s->get_result()->fetch_assoc();if(!$serv)jsonResponse(false,'Protocolo não encontrado.',[],404);$id=(int)$serv['id'];$h=$conn->prepare('SELECT status_novo,observacao,criado_em FROM servicos_historico WHERE servico_id=? ORDER BY id');$h->bind_param('i',$id);$h->execute();$serv['historico']=$h->get_result()->fetch_all(MYSQLI_ASSOC);jsonResponse(true,'',['servico'=>$serv]);
